from pathlib import Path
text=Path('/app/benchmark/source_brief.md').read_text().splitlines()
# extract sections by heading
heads=['## Digital Downloads Value Proposition','## Supported File Types','## Membership Benefits','## Membership Resources','## Tools That Power Growth','## FAQ (Home)','## FAQ (Online Courses)','## FAQ (Digital Downloads)','## FAQ (Coaching)','## Product Demo (Online Courses)','## Social Proof']
idx={}
for i,line in enumerate(text):
    if line.strip() in heads:
        idx[line.strip()]=i
for h in heads:
    i=idx.get(h)
    if i is None:
        print('missing',h)
        continue
    print('\n'+h)
    for line in text[i:i+40]:
        if line.startswith('## ') and line.strip()!=h:
            break
        print(line)
